#!/bin/sh
# 🧾️ The closing proof inside ONE capacity grant, one process at a time: proof.sh <memory MB> [step…]
# Steps (default: all): heap (the olive tree at the default and at a 256 MB young space), big (the resident set of the olive tree and of two of the largest assets for at most 900 s each; a process above BIG_LIMIT_KB resident, default 2.2 GB, is stopped), tsc (type check of the staffage package), suite (the multiview coverage suite).
# Logs in <generated>/proof-<step>*.log, each with the resident peak and the times of /usr/bin/time -l.
# Do not edit this file while a run of it is in flight.
set -u
R=/Users/ueli/Documents/semio
S="$R/🎓️teaching/🏛️architecture/🧍️staffage"
M="$R/.🧬semio/🦑️repo/🎫️tickets/🎆️26/🌙️11/☀️22/GET-STAFFAGE-RUNNING-END-TO-END-AND-FINISH-ALL-STAFFAGE-TICKETS/🧰️matrix/MM"
G="$R/.🧬semio/🦑️repo/🎫️tickets/🎆️26/🌙️11/☀️22/GET-STAFFAGE-RUNNING-END-TO-END-AND-FINISH-ALL-STAFFAGE-TICKETS/🗑️generated/matrix/MM"
SP="${SP:-/private/tmp/claude-501/-Users-ueli-Documents-semio/77b365fc-dfc7-4b6f-9d54-4f0eb23231c9/scratchpad}"
BUN=$(ls ~/Library/Caches/semio/runtimes/bun/*/bun | head -1)
if [ "${1:-}" != "--inside" ]; then
  cd "$R" || exit 1
  memory=$1; shift
  exec repo capacity run --memory="$memory" -- sh "$M/proof.sh" --inside "$@"
fi
shift
[ $# -eq 0 ] && set -- heap big tsc suite
mkdir -p "$G"
cd "$R" || exit 1
line() { echo "$1: $(grep -E 'maximum resident| real |^exit|Tests |Test Files ' "$G/$1.log" | tr -s ' ' | tr '\n' ';')"; }
for step in "$@"; do
  case "$step" in
    heap)
      sh "$M/heap.sh" --inside olive-tree live 0 256 0 256 ;;
    big)
      for asset in olive-tree small-leaved-lime sleeping-person; do
        /usr/bin/time -l timeout 900 "$BUN" "$M/one.ts" --snapshot "$SP/snap/$asset.json" --out "$G/proof-big-$asset.cells.json" --probe > "$G/proof-big-$asset.log" 2>&1 &
        timed=$!
        while kill -0 $timed 2>/dev/null; do
          sleep 5
          for pid in $(pgrep -f "one.ts --snapshot $SP/snap/$asset.json"); do
            rss=$(ps -o rss= -p "$pid" 2>/dev/null | tr -d ' ')
            [ -n "$rss" ] && [ "$rss" -gt "${BIG_LIMIT_KB:-2200000}" ] && echo "[DEBUG] stopped at $rss KB resident, above the limit" >> "$G/proof-big-$asset.log" && kill -9 "$pid"
          done
        done
        wait $timed
        echo "exit $?" >> "$G/proof-big-$asset.log"; line "proof-big-$asset"
      done ;;
    tsc)
      /usr/bin/time -l timeout 1200 "$BUN" node_modules/typescript/bin/tsc --noEmit -p "$S/📦️packages/🟦️typescript/tsconfig.json" > "$G/proof-tsc.log" 2>&1
      echo "exit $?" >> "$G/proof-tsc.log"; line proof-tsc ;;
    suite)
      /usr/bin/time -l timeout 1800 "$BUN" node_modules/vitest/vitest.mjs run --configLoader native --reporter=verbose --config "$S/🧪️tests/🎚️config/🟦️.ts" "🔭️multiview-coverage" > "$G/proof-suite.log" 2>&1
      echo "exit $?" >> "$G/proof-suite.log"; line proof-suite ;;
  esac
done
